/**
 * What the AWS, Azure and GCP Terraform generators share: the file map they return, the Terraform
 * version floor and the generated-by header every `.tf` file starts with.
 */

/** A generated file: relative path → contents. */
export type TerraformFiles = Record<string, string>;

/** Terraform CLI version floor for the generated modules. */
export const TERRAFORM_REQUIRED_VERSION = ">= 1.9";

/** The deploy targets that have a Terraform reference stack. */
export type TerraformTarget = "aws" | "azure" | "gcp";

/** The comment block that opens every generated `.tf` file of `target`. */
export function terraformHeader(target: TerraformTarget): string {
  return `# Generated by \`storyshelf server init --target ${target}\`. Do not edit by hand;\n# re-run the scaffold or edit the generator in @storyshelf/cli.\n\n`;
}
